async fn greek_deity(Path(slug): Path<String>) -> impl IntoResponse {
    match GREEK_DEITIES.iter().find(|deity| deity.slug == slug) {
        Some(deity) => (StatusCode::OK, HtmlTemplate(GreekDeityTemplate { deity })).into_response(),
        None => (StatusCode::NOT_FOUND, "Greek deity page not found").into_response(),
    }
}

